import re

def parse_json(json_str):
    json_str = json_str.strip()
    if not json_str:
        raise ValueError("Empty string provided.")
    if not json_str.startswith('{') and not json_str.startswith('['):
        raise ValueError("Not a valid JSON string.")
    json_str = re.sub(r'\s+', '', json_str)
    if json_str.startswith('{'):
        return {parse_json(key): parse_json(value) for key, value in [item.split(':') for item in json_str[1:-1].split(',')] if item}
    elif json_str.startswith('['):
        return [parse_json(item) for item in json_str[1:-1].split(',')]
    elif json_str.isdigit():
        return int(json_str)
    elif json_str.replace('.', '', 1).isdigit():
        return float(json_str)
    elif json_str.lower() == 'true':
        return True
    elif json_str.lower() == 'false':
        return False
    elif json_str == 'null':
        return None
    else:
        return json_str

